@Test
public void testBrokerTenant() throws IOException, JSONException {
    // Create broker tenants
    for (int i = 1; i <= NUM_BROKER_TAGS; i++) {
        String brokerTag = BROKER_TAG_PREFIX + i;
        JSONObject payload = ControllerRequestBuilderUtil.buildBrokerTenantCreateRequestJSON(brokerTag, NUM_BROKERS_PER_TAG);
        sendPostRequest(_controllerRequestURLBuilder.forTenantCreate(), payload.toString());
        Assert.assertEquals(_helixAdmin.getInstancesInClusterWithTag(_helixClusterName, ControllerTenantNameBuilder.getBrokerTenantNameForTenant(brokerTag)).size(), NUM_BROKERS_PER_TAG);
        Assert.assertEquals(_helixAdmin.getInstancesInClusterWithTag(_helixClusterName, CommonConstants.Helix.UNTAGGED_BROKER_INSTANCE).size(), NUM_INSTANCES - i * NUM_BROKERS_PER_TAG);
    }
    // Get broker tenants
    JSONObject response = new JSONObject(sendGetRequest(_controllerRequestURLBuilder.forTenantGet()));
    Assert.assertEquals(response.getJSONArray("BROKER_TENANTS").length(), NUM_BROKER_TAGS);
    for (int i = 1; i <= NUM_BROKER_TAGS; i++) {
        String brokerTag = BROKER_TAG_PREFIX + i;
        response = new JSONObject(sendGetRequest(_controllerRequestURLBuilder.forBrokerTenantGet(brokerTag)));
        Assert.assertEquals(response.getJSONArray("BrokerInstances").length(), NUM_BROKERS_PER_TAG);
        Assert.assertEquals(response.getString("tenantName"), brokerTag);
        response = new JSONObject(sendGetRequest(_controllerRequestURLBuilder.forTenantGet(brokerTag)));
        Assert.assertEquals(response.getJSONArray("BrokerInstances").length(), NUM_BROKERS_PER_TAG);
        Assert.assertEquals(response.getJSONArray("ServerInstances").length(), 0);
        Assert.assertEquals(response.getString("tenantName"), brokerTag);
    }
    // Update broker tenants
    for (int i = 0; i <= NUM_INSTANCES - (NUM_BROKER_TAGS - 1) * NUM_BROKERS_PER_TAG; i++) {
        String brokerTag = BROKER_TAG_PREFIX + 1;
        JSONObject payload = ControllerRequestBuilderUtil.buildBrokerTenantCreateRequestJSON(brokerTag, i);
        sendPutRequest(_controllerRequestURLBuilder.forTenantCreate(), payload.toString());
        Assert.assertEquals(_helixAdmin.getInstancesInClusterWithTag(_helixClusterName, ControllerTenantNameBuilder.getBrokerTenantNameForTenant(brokerTag)).size(), i);
        Assert.assertEquals(_helixAdmin.getInstancesInClusterWithTag(_helixClusterName, CommonConstants.Helix.UNTAGGED_BROKER_INSTANCE).size(), NUM_INSTANCES - (NUM_BROKER_TAGS - 1) * NUM_BROKERS_PER_TAG - i);
    }
    // Delete broker tenants
    for (int i = 1; i <= NUM_BROKER_TAGS; i++) {
        String brokerTag = BROKER_TAG_PREFIX + i;
        sendDeleteRequest(_controllerRequestURLBuilder.forBrokerTenantDelete(brokerTag));
        Assert.assertEquals(_helixAdmin.getInstancesInClusterWithTag(_helixClusterName, ControllerTenantNameBuilder.getBrokerTenantNameForTenant(brokerTag)).size(), 0);
        Assert.assertEquals(_helixAdmin.getInstancesInClusterWithTag(_helixClusterName, CommonConstants.Helix.UNTAGGED_BROKER_INSTANCE).size(), NUM_INSTANCES - (NUM_BROKER_TAGS - i) * NUM_BROKERS_PER_TAG);
    }
}

@Test
public void testServerTenant() throws IOException, JSONException {
    // Create server tenants
    for (int i = 1; i <= NUM_SERVER_TAGS; i++) {
        String serverTag = SERVER_TAG_PREFIX + i;
        JSONObject payload = ControllerRequestBuilderUtil.buildServerTenantCreateRequestJSON(serverTag, NUM_SERVERS_PER_TAG, NUM_OFFLINE_SERVERS_PER_TAG, NUM_REALTIME_SERVERS_PER_TAG);
        sendPostRequest(_controllerRequestURLBuilder.forTenantCreate(), payload.toString());
        Assert.assertEquals(_helixAdmin.getInstancesInClusterWithTag(_helixClusterName, ControllerTenantNameBuilder.getOfflineTenantNameForTenant(serverTag)).size(), NUM_OFFLINE_SERVERS_PER_TAG);
        Assert.assertEquals(_helixAdmin.getInstancesInClusterWithTag(_helixClusterName, ControllerTenantNameBuilder.getRealtimeTenantNameForTenant(serverTag)).size(), NUM_REALTIME_SERVERS_PER_TAG);
        Assert.assertEquals(_helixAdmin.getInstancesInClusterWithTag(_helixClusterName, CommonConstants.Helix.UNTAGGED_SERVER_INSTANCE).size(), NUM_INSTANCES - i * NUM_SERVERS_PER_TAG);
    }
    // Get server tenants
    JSONObject response = new JSONObject(sendGetRequest(_controllerRequestURLBuilder.forTenantGet()));
    Assert.assertEquals(response.getJSONArray("SERVER_TENANTS").length(), NUM_SERVER_TAGS);
    for (int i = 1; i <= NUM_SERVER_TAGS; i++) {
        String serverTag = SERVER_TAG_PREFIX + i;
        response = new JSONObject(sendGetRequest(_controllerRequestURLBuilder.forServerTenantGet(serverTag)));
        Assert.assertEquals(response.getJSONArray("ServerInstances").length(), NUM_SERVERS_PER_TAG);
        Assert.assertEquals(response.getString("tenantName"), serverTag);
        response = new JSONObject(sendGetRequest(_controllerRequestURLBuilder.forTenantGet(serverTag)));
        Assert.assertEquals(response.getJSONArray("BrokerInstances").length(), 0);
        Assert.assertEquals(response.getJSONArray("ServerInstances").length(), NUM_SERVERS_PER_TAG);
        Assert.assertEquals(response.getString("tenantName"), serverTag);
    }
    // Update server tenants
    // Note: server tenants cannot scale down
    for (int i = 0; i <= (NUM_INSTANCES - NUM_SERVER_TAGS * NUM_SERVERS_PER_TAG) / 2; i++) {
        String serverTag = SERVER_TAG_PREFIX + 1;
        JSONObject payload = ControllerRequestBuilderUtil.buildServerTenantCreateRequestJSON(serverTag, NUM_SERVERS_PER_TAG + i * 2, NUM_OFFLINE_SERVERS_PER_TAG + i, NUM_REALTIME_SERVERS_PER_TAG + i);
        sendPutRequest(_controllerRequestURLBuilder.forTenantCreate(), payload.toString());
        Assert.assertEquals(_helixAdmin.getInstancesInClusterWithTag(_helixClusterName, ControllerTenantNameBuilder.getOfflineTenantNameForTenant(serverTag)).size(), NUM_OFFLINE_SERVERS_PER_TAG + i);
        Assert.assertEquals(_helixAdmin.getInstancesInClusterWithTag(_helixClusterName, ControllerTenantNameBuilder.getRealtimeTenantNameForTenant(serverTag)).size(), NUM_REALTIME_SERVERS_PER_TAG + i);
        Assert.assertEquals(_helixAdmin.getInstancesInClusterWithTag(_helixClusterName, CommonConstants.Helix.UNTAGGED_SERVER_INSTANCE).size(), NUM_INSTANCES - NUM_SERVER_TAGS * NUM_SERVERS_PER_TAG - i * 2);
    }
    // Delete server tenants
    for (int i = 1; i < NUM_SERVER_TAGS; i++) {
        String serverTag = SERVER_TAG_PREFIX + i;
        sendDeleteRequest(_controllerRequestURLBuilder.forServerTenantDelete(serverTag));
        Assert.assertEquals(_helixAdmin.getInstancesInClusterWithTag(_helixClusterName, ControllerTenantNameBuilder.getOfflineTenantNameForTenant(serverTag)).size(), 0);
        Assert.assertEquals(_helixAdmin.getInstancesInClusterWithTag(_helixClusterName, ControllerTenantNameBuilder.getRealtimeTenantNameForTenant(serverTag)).size(), 0);
        Assert.assertEquals(_helixAdmin.getInstancesInClusterWithTag(_helixClusterName, CommonConstants.Helix.UNTAGGED_SERVER_INSTANCE).size(), NUM_INSTANCES - (NUM_SERVER_TAGS - i) * NUM_SERVERS_PER_TAG);
    }
}

