public void testRebuildBrokerResourceFromHelixTags() throws Exception {
    // Create broker tenant on 3 Brokers
    Tenant brokerTenant = new Tenant.TenantBuilder(BROKER_TENANT_NAME).setRole(TenantRole.BROKER).setTotalInstances(3).build();
    _helixResourceManager.createBrokerTenant(brokerTenant);
