/**
 * This test ensures the FilterQueryTree & InPredicate are constructed correctly for both cases of:
 * <ul>
 *   <li> Splitting the in clause values. </li>
 *   <li> Joining the in clause values with delimiter. </li>
 * </ul>
 */
@Test
public void testSplitInClause() {
    Pql2Compiler compiler = new Pql2Compiler();
    String query = "select * from foo where values in ('abc', 'xyz', '123')";
    String[] expectedValues = new String[] { "abc", "xyz", "123" };
    Arrays.sort(expectedValues);
    /* InPredicateAstNode sorts the predicate values. */
    /* Test split case */
    BrokerRequest brokerRequest = compiler.compileToBrokerRequest(query, true);
    FilterQueryTree filterQueryTree = RequestUtils.generateFilterQueryTree(brokerRequest);
    InPredicate predicate = (InPredicate) Predicate.newPredicate(filterQueryTree);
    String[] actualValues = predicate.getInRange();
    Arrays.sort(actualValues);
    Assert.assertEquals(actualValues, expectedValues);
    Assert.assertTrue(EqualityUtils.isEqualIgnoreOrder(filterQueryTree.getValue(), Arrays.asList(expectedValues)));
    /* Test join case */
    brokerRequest = compiler.compileToBrokerRequest(query, false);
    filterQueryTree = RequestUtils.generateFilterQueryTree(brokerRequest);
    predicate = (InPredicate) Predicate.newPredicate(filterQueryTree);
    actualValues = predicate.getInRange();
    Arrays.sort(actualValues);
    Assert.assertEquals(actualValues, expectedValues);
    actualValues = filterQueryTree.getValue().get(0).split(InPredicate.DELIMITER);
    Arrays.sort(actualValues);
    Assert.assertEquals(actualValues, expectedValues);
}

@Test
public void testIntPredicateEvaluators() {
    int intValue = _random.nextInt();
    EqPredicate eqPredicate = new EqPredicate(COLUMN_NAME, Collections.singletonList(Integer.toString(intValue)));
    PredicateEvaluator eqPredicateEvaluator = EqualsPredicateEvaluatorFactory.newRawValueBasedEvaluator(eqPredicate, FieldSpec.DataType.INT);
    NEqPredicate neqPredicate = new NEqPredicate(COLUMN_NAME, Collections.singletonList(Integer.toString(intValue)));
    PredicateEvaluator neqPredicateEvaluator = NotEqualsPredicateEvaluatorFactory.newRawValueBasedEvaluator(neqPredicate, FieldSpec.DataType.INT);
    Assert.assertTrue(eqPredicateEvaluator.applySV(intValue));
    Assert.assertFalse(neqPredicateEvaluator.applySV(intValue));
    int[] randomInts = new int[NUM_MULTI_VALUES];
    PredicateEvaluatorTestUtils.fillRandom(randomInts);
    randomInts[_random.nextInt(NUM_MULTI_VALUES)] = intValue;
    Assert.assertTrue(eqPredicateEvaluator.applyMV(randomInts, NUM_MULTI_VALUES));
    Assert.assertFalse(neqPredicateEvaluator.applyMV(randomInts, NUM_MULTI_VALUES));
    for (int i = 0; i < 100; i++) {
        int random = _random.nextInt();
        Assert.assertEquals(eqPredicateEvaluator.applySV(random), (random == intValue));
        Assert.assertEquals(neqPredicateEvaluator.applySV(random), (random != intValue));
        PredicateEvaluatorTestUtils.fillRandom(randomInts);
        Assert.assertEquals(eqPredicateEvaluator.applyMV(randomInts, NUM_MULTI_VALUES), ArrayUtils.contains(randomInts, intValue));
        Assert.assertEquals(neqPredicateEvaluator.applyMV(randomInts, NUM_MULTI_VALUES), !ArrayUtils.contains(randomInts, intValue));
    }
}

