    }
    readBuf.close();
    PinotDataBuffer heapReadBuf = PinotDataBuffer.fromFile(file, ReadMode.heap, FileChannel.MapMode.READ_ONLY, "testing");
    pos = 0;
    for (int i = 0; i < data.length; ++i, ++pos) {
        Assert.assertEquals(data[i], heapReadBuf.getInt(pos * 4));
    }
    heapReadBuf.close();
}

